import { useState } from 'react';

function RentModal({ vehicle, user, token, onClose, onSuccess }) {
  const [step, setStep] = useState(1);
  const [dates, setDates] = useState({ start: '', end: '' });
  const [cardInfo, setCardInfo] = useState({ number: '', name: '', expiry: '', cvv: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const today = new Date().toISOString().split('T')[0];

  const calcDays = () => {
    if (!dates.start || !dates.end) return 0;
    const diff = new Date(dates.end) - new Date(dates.start);
    return Math.max(1, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  };

  const totalAmount = calcDays() * vehicle.pricePerDay;

  const handlePayment = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const res = await fetch('http://localhost:3003/api/reservations', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          userId: user.id,
          renterName: user.name,
          vehicleId: vehicle.id,
          startDate: dates.start,
          endDate: dates.end,
          amount: totalAmount,
          cardInfo,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Rezervasyon başarısız.');
      onSuccess(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>✕</button>

        {step === 1 && (
          <>
            <h2>Araç Kiralama</h2>
            <div className="vehicle-summary">
              <h3>🚗 {vehicle.brand} {vehicle.model}</h3>
              <p>{vehicle.campus} &bull; {vehicle.segment}</p>
              <p className="price">₺{vehicle.pricePerDay}/gün</p>
            </div>
            <div className="date-inputs">
              <label>
                Başlangıç Tarihi
                <input
                  type="date"
                  value={dates.start}
                  min={today}
                  onChange={(e) => setDates({ ...dates, start: e.target.value })}
                  required
                />
              </label>
              <label>
                Bitiş Tarihi
                <input
                  type="date"
                  value={dates.end}
                  min={dates.start || today}
                  onChange={(e) => setDates({ ...dates, end: e.target.value })}
                  required
                />
              </label>
            </div>
            {calcDays() > 0 && (
              <div className="total">
                <span>{calcDays()} gün × ₺{vehicle.pricePerDay}</span>
                <strong>Toplam: ₺{totalAmount}</strong>
              </div>
            )}
            <button
              className="rent-btn"
              onClick={() => setStep(2)}
              disabled={!dates.start || !dates.end}
            >
              Ödemeye Geç →
            </button>
          </>
        )}

        {step === 2 && (
          <form onSubmit={handlePayment}>
            <h2>Ödeme Bilgileri</h2>
            <p className="payment-note">🔒 Güvenli Escrow Ödeme Sistemi</p>
            <input
              placeholder="Kart Numarası (16 hane)"
              value={cardInfo.number}
              onChange={(e) => setCardInfo({ ...cardInfo, number: e.target.value })}
              maxLength={19}
              required
            />
            <input
              placeholder="Kart Üzerindeki İsim"
              value={cardInfo.name}
              onChange={(e) => setCardInfo({ ...cardInfo, name: e.target.value })}
              required
            />
            <div className="card-row">
              <input
                placeholder="AA/YY"
                value={cardInfo.expiry}
                onChange={(e) => setCardInfo({ ...cardInfo, expiry: e.target.value })}
                maxLength={5}
                required
              />
              <input
                placeholder="CVV"
                value={cardInfo.cvv}
                onChange={(e) => setCardInfo({ ...cardInfo, cvv: e.target.value })}
                maxLength={3}
                type="password"
                required
              />
            </div>
            <div className="total">
              <strong>Ödenecek Tutar: ₺{totalAmount}</strong>
            </div>
            {error && <p className="error">{error}</p>}
            <button type="submit" className="pay-btn" disabled={loading}>
              {loading ? 'İşleniyor...' : 'Ödemeyi Tamamla'}
            </button>
            <button type="button" className="back-btn" onClick={() => setStep(1)}>
              ← Geri
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

export default RentModal;
